// Writes src/puzzles/examples.generated.ts with the contents of the example puzzle files, so
// the app has them on every platform without file access. Run after changing an example:
//   npm run examples -w @constraintpuzzler/app
// (src/puzzles/examples.test.ts fails when the generated file is out of date.)
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const app = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const root = resolve(app, '..');
const registry = readFileSync(join(root, 'packages/core/src/puzzletypes.ts'), 'utf-8');
const files = [...registry.matchAll(/'([A-Za-z0-9_-]+\.txt)'/g)].map((m) => m[1]);

const entries = files
  .map((file) => {
    const text = readFileSync(join(root, file), 'utf-8').replaceAll('\r\n', '\n');
    return `  ${JSON.stringify(file)}: ${JSON.stringify(text)},`;
  })
  .join('\n');

writeFileSync(
  join(app, 'src/puzzles/examples.generated.ts'),
  `// Generated by scripts/bundle-examples.mjs from the example puzzle files; do not edit.\n` +
    `export const EXAMPLES: Readonly<Record<string, string>> = {\n${entries}\n};\n`,
);
console.log(`bundled ${files.length} example puzzles`);
